/**
 * Server-side data fetcher for the Next Up widget.
 * Returns the next 3 confirmed/in_progress bookings starting >= now, today.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Return types ─────────────────────────────────────────────────────────────

export interface NextUpItem {
  id: string
  scheduledAt: string
  /** "in 45 min" | "now" | null */
  relativeLabel: string | null
  durationMin: number
  clientName: string
  clientInitials: string
  artistId: string
  artistName: string
  /** hex string from artists.calendar_color — may be null */
  artistColor: string | null
  serviceName: string | null
  /** "S3/5" if project-linked, else null */
  sessionLabel: string | null
  depositPaid: boolean
  depositCents: number
  /** True if consent is required and NOT yet signed */
  consentRequired: boolean
  consentSigned: boolean
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function buildInitials(name: string): string {
  return name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase() ?? '')
    .join('')
}

function computeRelativeLabel(scheduledAt: string): string | null {
  const diff = new Date(scheduledAt).getTime() - Date.now()
  if (diff < 0) return 'now'
  const mins = Math.round(diff / 60_000)
  if (mins < 60) return `in ${mins} min`
  const hrs = Math.floor(mins / 60)
  const rem = mins % 60
  if (rem === 0) return `in ${hrs}h`
  return `in ${hrs}h ${rem}m`
}

function todayIso(): string {
  // YYYY-MM-DD in local time
  return new Date().toISOString().slice(0, 10)
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getNextUpItems(
  supabase: SupabaseClient,
  studioId: string,
): Promise<NextUpItem[]> {
  const now = new Date().toISOString()
  const today = todayIso()

  // End of today UTC (conservative: add 1 day to today date)
  const endOfToday = `${today}T23:59:59.999Z`

  const { data, error } = await supabase
    .from('bookings')
    .select(`
      id,
      scheduled_at,
      duration_min,
      deposit_paid,
      deposit_cents,
      consent_required,
      consent_signed_at,
      project_id,
      session_number,
      clients!inner(first_name, last_name),
      artists!inner(id, display_name, calendar_color),
      services(name)
    `)
    .eq('studio_id', studioId)
    .gte('scheduled_at', now)
    .lte('scheduled_at', endOfToday)
    .in('status', ['confirmed', 'in_progress'])
    .order('scheduled_at', { ascending: true })
    .limit(3)

  if (error) {
    return []
  }

  type Row = {
    id: string
    scheduled_at: string
    duration_min: number
    deposit_paid: boolean
    deposit_cents: number
    consent_required: boolean
    consent_signed_at: string | null
    project_id: string | null
    session_number: number | null
    clients: { first_name: string; last_name: string | null }
    artists: { id: string; display_name: string; calendar_color: string | null }
    services: { name: string } | null
  }

  return ((data ?? []) as Row[]).map((row): NextUpItem => {
    const clientName = `${row.clients.first_name} ${row.clients.last_name ?? ''}`.trim()
    return {
      id: row.id,
      scheduledAt: row.scheduled_at,
      relativeLabel: computeRelativeLabel(row.scheduled_at),
      durationMin: row.duration_min,
      clientName,
      clientInitials: buildInitials(clientName),
      artistId: row.artists.id,
      artistName: row.artists.display_name,
      artistColor: row.artists.calendar_color,
      serviceName: row.services?.name ?? null,
      sessionLabel:
        row.project_id && row.session_number ? `S${row.session_number}` : null,
      depositPaid: row.deposit_paid,
      depositCents: row.deposit_cents,
      consentRequired: row.consent_required,
      consentSigned: row.consent_required ? row.consent_signed_at !== null : true,
    }
  })
}

/**
 * Server-side data fetcher for the Today's Schedule Timeline widget.
 * Returns all bookings for today grouped by artist, plus studio hours.
 */

type SupabaseClient = Awaited<ReturnType<typeof import('@/lib/supabase/server').createClient>>

// ─── Return types ─────────────────────────────────────────────────────────────

export interface ScheduleBooking {
  id: string
  clientName: string
  scheduledAt: string
  endAt: string
  durationMin: number
  serviceName: string | null
  depositPaid: boolean
  notes: string | null
}

export interface ScheduleArtist {
  id: string
  name: string
  /** hex string or null — from artists.calendar_color */
  color: string | null
  /** True if the artist is a guest (no profile, external) */
  isGuest: boolean
  bookings: ScheduleBooking[]
}

export interface TodayScheduleData {
  artists: ScheduleArtist[]
  /** 24h string "10:00" */
  openTime: string
  /** 24h string "22:00" */
  closeTime: string
  /** True if studio is closed today (operating_hours says so) */
  closedToday: boolean
  hasBookings: boolean
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function todayIso(): string {
  return new Date().toISOString().slice(0, 10)
}

function todayDayOfWeek(): number {
  return new Date().getDay() // 0=Sun..6=Sat
}

// ─── Main fetch ───────────────────────────────────────────────────────────────

export async function getTodayScheduleData(
  supabase: SupabaseClient,
  studioId: string,
): Promise<TodayScheduleData> {
  const today = todayIso()

  // Studio hours query
  const [bookingsRes, hoursRes] = await Promise.all([
    supabase
      .from('bookings')
      .select(`
        id,
        scheduled_at,
        end_at,
        duration_min,
        deposit_paid,
        notes,
        clients!inner(first_name, last_name),
        artists!inner(id, display_name, calendar_color, profile_id),
        services(name)
      `)
      .eq('studio_id', studioId)
      .gte('scheduled_at', `${today}T00:00:00.000Z`)
      .lte('scheduled_at', `${today}T23:59:59.999Z`)
      .in('status', ['pending', 'confirmed', 'in_progress', 'completed'])
      .order('scheduled_at', { ascending: true }),

    supabase
      .from('operating_hours')
      .select('day_of_week, open_time, close_time')
      .eq('studio_id', studioId)
      .eq('day_of_week', todayDayOfWeek()),
  ])

  type BookingRow = {
    id: string
    scheduled_at: string
    end_at: string
    duration_min: number
    deposit_paid: boolean
    notes: string | null
    clients: { first_name: string; last_name: string | null }
    artists: { id: string; display_name: string; calendar_color: string | null; profile_id: string | null }
    services: { name: string } | null
  }

  const bookings = ((bookingsRes.data ?? []) as BookingRow[])

  // Determine hours
  const hoursRow = hoursRes.data?.[0]
  // Default 10:00–22:00 when no DB record
  const openTime = hoursRow?.open_time ?? '10:00'
  const closeTime = hoursRow?.close_time ?? '22:00'
  // closedToday: if operating_hours has no record for today, treat as open (default)
  // We only close if there's an explicit record that matches? Use absence = open for now.
  // Future: add an `is_closed` boolean to operating_hours
  const closedToday = false

  // Group by artist
  const artistMap = new Map<string, ScheduleArtist>()

  for (const row of bookings) {
    const { id: artistId, display_name, calendar_color, profile_id } = row.artists
    if (!artistMap.has(artistId)) {
      artistMap.set(artistId, {
        id: artistId,
        name: display_name,
        color: calendar_color,
        isGuest: profile_id === null,
        bookings: [],
      })
    }

    const clientName = `${row.clients.first_name} ${row.clients.last_name ?? ''}`.trim()
    artistMap.get(artistId)!.bookings.push({
      id: row.id,
      clientName,
      scheduledAt: row.scheduled_at,
      endAt: row.end_at,
      durationMin: row.duration_min,
      serviceName: row.services?.name ?? null,
      depositPaid: row.deposit_paid,
      notes: row.notes,
    })
  }

  const artists = Array.from(artistMap.values())

  return {
    artists,
    openTime,
    closeTime,
    closedToday,
    hasBookings: bookings.length > 0,
  }
}

