'use client'

import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useTransition } from 'react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { logger } from '@/lib/logger'
import { sendDepositReminderAction, resendFormLinkAction } from '@/app/(app)/inbox/actions'
import type { NextUpItem } from '@/lib/dashboard/next-up'
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuTrigger,
} from '@/components/ui/context-menu'

// ─── Props ─────────────────────────────────────────────────────────────────────

interface NextUpWidgetProps {
  items: NextUpItem[]
}

// ─── Avatar ───────────────────────────────────────────────────────────────────

function ArtistAvatar({
  initials,
  artistColor,
  size = 'md',
}: {
  initials: string
  artistColor: string | null
  size?: 'sm' | 'md'
}) {
  const dim = size === 'sm' ? 'h-7 w-7 text-[10px]' : 'h-9 w-9 text-[11px]'

  if (artistColor) {
    // Color-mix with transparency for bg, raw color for ring — mirrors ArtistCard.tsx pattern
    const bg = `color-mix(in srgb, ${artistColor} 18%, transparent)`
    return (
      <span
        className={cn(
          'inline-flex shrink-0 items-center justify-center rounded-full font-semibold',
          dim,
        )}
        style={{ backgroundColor: bg, color: artistColor }}
        aria-hidden="true"
      >
        {initials}
      </span>
    )
  }

  return (
    <span
      className={cn(
        'inline-flex shrink-0 items-center justify-center rounded-full font-semibold',
        'bg-[var(--color-muted)] text-[var(--color-muted-foreground)]',
        dim,
      )}
      aria-hidden="true"
    >
      {initials}
    </span>
  )
}

// ─── Status pill ──────────────────────────────────────────────────────────────

type PillVariant = 'success' | 'destructive' | 'muted'

function StatusPill({
  label,
  variant,
  onClick,
  loading,
}: {
  label: string
  variant: PillVariant
  onClick?: () => void
  loading?: boolean
}) {
  const base = 'inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold transition-opacity'
  const styles: Record<PillVariant, string> = {
    success:
      'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)] cursor-default',
    destructive:
      'bg-[rgba(178,58,43,0.10)] text-[var(--color-rust)] cursor-pointer hover:opacity-80 active:opacity-60',
    muted:
      'bg-[var(--color-muted)] text-[var(--color-muted-foreground)] cursor-pointer hover:opacity-80 active:opacity-60',
  }

  if (onClick) {
    return (
      <button
        type="button"
        className={cn(base, styles[variant], loading && 'pointer-events-none opacity-50')}
        onClick={(e) => {
          e.stopPropagation()
          onClick()
        }}
        disabled={loading}
        aria-label={label}
      >
        {label}
      </button>
    )
  }

  return (
    <span className={cn(base, styles[variant])}>
      {label}
    </span>
  )
}

// ─── Time display ─────────────────────────────────────────────────────────────

function formatTime(iso: string): string {
  return new Date(iso).toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  })
}

// ─── Booking card ─────────────────────────────────────────────────────────────

function BookingCard({
  item,
  isFirst,
}: {
  item: NextUpItem
  isFirst: boolean
}) {
  const router = useRouter()
  const [depositPending, startDeposit] = useTransition()
  const [consentPending, startConsent] = useTransition()

  function handleDepositPill() {
    startDeposit(async () => {
      const result = await sendDepositReminderAction(item.id)
      if (result.ok) {
        toast.success('Reminder sent.')
      } else {
        toast.error(result.error ?? 'Failed to send reminder.')
        logger.error({ bookingId: item.id, error: result.error }, 'next-up: deposit reminder failed')
      }
    })
  }

  function handleConsentPill() {
    startConsent(async () => {
      const result = await resendFormLinkAction(item.id)
      if (result.ok) {
        toast.success('Form resent.')
      } else {
        toast.error(result.error ?? 'Failed to resend form.')
        logger.error({ bookingId: item.id, error: result.error }, 'next-up: consent resend failed')
      }
    })
  }

  function handleCardClick() {
    router.push(`/bookings/${item.id}`)
  }

  // Build subtitle: "Service · S3 · 90 min · Lena"
  const subtitleParts: string[] = []
  if (item.serviceName) subtitleParts.push(item.serviceName)
  if (item.sessionLabel) subtitleParts.push(item.sessionLabel)
  subtitleParts.push(`${item.durationMin} min`)
  subtitleParts.push(item.artistName)

  // Deposit status
  const depositOverdue = !item.depositPaid && item.depositCents > 0
  // Consent status
  const consentUnsigned = item.consentRequired && !item.consentSigned

  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <button
          type="button"
          onClick={handleCardClick}
          className={cn(
            'group w-full rounded-lg border p-3 text-left transition-all duration-150',
            'hover:shadow-[var(--shadow-card-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)] focus-visible:ring-offset-2',
            isFirst
              ? 'border-l-2 border-l-[var(--color-rust)] border-[var(--color-border)] bg-[var(--color-accent)]'
              : 'border-[var(--color-border)] bg-[var(--color-card)] hover:bg-[var(--color-secondary)]',
          )}
          aria-label={`Booking for ${item.clientName} at ${formatTime(item.scheduledAt)}`}
        >
          <div className="flex items-start gap-3">
            {/* Time column */}
            <div className="shrink-0 text-right">
              <p className="tabular-nums text-[13px] font-bold leading-tight text-[var(--color-foreground)]">
                {formatTime(item.scheduledAt)}
              </p>
              {item.relativeLabel && (
                <p className="mt-0.5 tabular-nums text-[10px] leading-tight text-[var(--color-muted-foreground)]">
                  {item.relativeLabel}
                </p>
              )}
            </div>

            {/* Avatar */}
            <ArtistAvatar initials={item.clientInitials} artistColor={item.artistColor} />

            {/* Main content */}
            <div className="min-w-0 flex-1">
