'use client'

import { useEffect, useRef, useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { cn } from '@/lib/utils'
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import type { TodayScheduleData, ScheduleBooking, ScheduleArtist } from '@/lib/dashboard/today-schedule'

// ─── Props ─────────────────────────────────────────────────────────────────────

interface TodayScheduleTimelineWidgetProps {
  data: TodayScheduleData
}

// ─── Time helpers ─────────────────────────────────────────────────────────────

/** Parse "HH:MM" → minutes since midnight */
function parseMins(time: string): number {
  const [h, m] = time.split(':').map(Number)
  return (h ?? 0) * 60 + (m ?? 0)
}

/** ISO timestamp → minutes since midnight (local) */
function isoToMins(iso: string): number {
  const d = new Date(iso)
  return d.getHours() * 60 + d.getMinutes()
}

/** Minutes since midnight → "H:MM AM" */
function minsToLabel(mins: number): string {
  const h = Math.floor(mins / 60)
  const m = mins % 60
  const suffix = h >= 12 ? 'PM' : 'AM'
  const displayH = h % 12 === 0 ? 12 : h % 12
  return m === 0 ? `${displayH} ${suffix}` : `${displayH}:${String(m).padStart(2, '0')} ${suffix}`
}

/** Current minutes since midnight */
function nowMins(): number {
  const d = new Date()
  return d.getHours() * 60 + d.getMinutes()
}

// ─── Now line ─────────────────────────────────────────────────────────────────

function NowLine({
  openMins,
  totalMins,
}: {
  openMins: number
  totalMins: number
}) {
  const [pct, setPct] = useState<number | null>(null)

  useEffect(() => {
    function update() {
      const mins = nowMins()
      if (mins < openMins || mins > openMins + totalMins) {
        setPct(null)
        return
      }
      setPct(((mins - openMins) / totalMins) * 100)
    }

    update()
    const id = setInterval(update, 60_000)
    return () => clearInterval(id)
  }, [openMins, totalMins])

  if (pct === null) return null

  return (
    <div
      role="presentation"
      aria-hidden="true"
      className="pointer-events-none absolute inset-y-0 z-10 flex flex-col items-center"
      style={{ left: `${pct}%` }}
    >
      {/* Vertical line */}
      <div className="h-full w-[2px] bg-[var(--color-destructive)]" />
      {/* Dot at top */}
      <div
        className="absolute top-0 h-2.5 w-2.5 -translate-x-[calc(50%-1px)] -translate-y-1 rounded-full bg-[var(--color-destructive)]"
      />
    </div>
  )
}

// ─── Booking block ────────────────────────────────────────────────────────────

function BookingBlock({
  booking,
  artistColor,
  openMins,
  totalMins,
}: {
  booking: ScheduleBooking
  artistColor: string | null
  openMins: number
  totalMins: number
}) {
  const router = useRouter()
  const startMins = isoToMins(booking.scheduledAt)
  const endMins = startMins + booking.durationMin

  // Clamp within visible range
  const clampedStart = Math.max(startMins, openMins)
  const clampedEnd = Math.min(endMins, openMins + totalMins)

  if (clampedEnd <= clampedStart) return null

  const leftPct = ((clampedStart - openMins) / totalMins) * 100
  const widthPct = ((clampedEnd - clampedStart) / totalMins) * 100

  const bg = artistColor
    ? `color-mix(in srgb, ${artistColor} 22%, transparent)`
    : 'var(--color-muted)'

  const textColor = artistColor ?? 'var(--color-foreground)'

  const label = `${booking.clientName} · ${minsToLabel(startMins)}–${minsToLabel(endMins)}`

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          onClick={() => router.push(`/bookings/${booking.id}`)}
          className={cn(
            'absolute inset-y-1 rounded overflow-hidden text-left',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]',
            'hover:brightness-95 transition-[filter] duration-100',
          )}
          style={{
            left: `${leftPct}%`,
            width: `${widthPct}%`,
            backgroundColor: bg,
            borderLeft: `2px solid ${artistColor ?? 'var(--color-border)'}`,
          }}
          aria-label={label}
        >
          <span
            className="block truncate px-1 text-[9px] font-semibold leading-tight"
            style={{ color: textColor }}
          >
            {label}
          </span>
        </button>
      </TooltipTrigger>
      <TooltipContent
        side="top"
        className="max-w-[220px] space-y-0.5 rounded-lg border border-[var(--color-border)] bg-[var(--color-card)] p-2.5 shadow-[var(--shadow-lift)] text-[var(--color-foreground)]"
      >
        <p className="text-[11px] font-semibold">{booking.clientName}</p>
        {booking.serviceName && (
          <p className="text-[10px] text-[var(--color-muted-foreground)]">{booking.serviceName}</p>
        )}
        <p className="text-[10px] tabular-nums text-[var(--color-muted-foreground)]">
          {minsToLabel(startMins)} – {minsToLabel(endMins)} · {booking.durationMin} min
        </p>
        <p className="text-[10px] text-[var(--color-muted-foreground)]">
          Deposit: {booking.depositPaid ? 'paid' : 'pending'}
        </p>
        {booking.notes && (
          <p className="text-[10px] text-[var(--color-muted-foreground)] line-clamp-2">
            {booking.notes}
          </p>
        )}
      </TooltipContent>
    </Tooltip>
  )
}

// ─── Artist row ───────────────────────────────────────────────────────────────

const ROW_HEIGHT = 44

function ArtistRow({
  artist,
  openMins,
  totalMins,
  rowIndex,
}: {
  artist: ScheduleArtist
  openMins: number
  totalMins: number
  rowIndex: number
}) {
  const router = useRouter()

  function handleEmptyClick(e: React.MouseEvent<HTMLDivElement>) {
    // Ignore clicks that originated from a booking block button
    if ((e.target as HTMLElement).closest('button')) return

    // Calculate approximate time from click x
    const rect = e.currentTarget.getBoundingClientRect()
    const x = e.clientX - rect.left
    const pct = x / rect.width
    const clickedMins = openMins + Math.round(pct * totalMins)
    const h = Math.floor(clickedMins / 60)
    const m = Math.round((clickedMins % 60) / 15) * 15
    const startTime = `${String(h).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`

    router.push(`/appointments/new?artist_id=${encodeURIComponent(artist.id)}&start=${encodeURIComponent(startTime)}`)
  }

  return (
    <div
      className={cn(
        'flex',
        rowIndex % 2 === 0 ? 'bg-[var(--color-card)]' : 'bg-[var(--color-secondary)]',
      )}
      style={{ height: ROW_HEIGHT }}
    >
      {/* Artist label */}
      <div
        className="flex shrink-0 items-center gap-1.5 border-r border-[var(--color-border)] px-2"
        style={{ width: 96 }}
      >
        {artist.artistColor && (
          <span
            className="h-2 w-2 shrink-0 rounded-full"
            style={{ backgroundColor: artist.artistColor }}
            aria-hidden="true"
          />
        )}
        <span className="truncate text-[10px] font-semibold text-[var(--color-foreground)]">
          {artist.name}
        </span>
        {artist.isGuest && (
          <span className="shrink-0 rounded-full bg-[var(--color-muted)] px-1 py-px text-[8px] font-bold uppercase tracking-wider text-[var(--color-muted-foreground)]">
            Guest
          </span>
        )}
      </div>

      {/* Timeline */}
      <div
        className="relative flex-1 cursor-pointer"
        onClick={handleEmptyClick}
        role="button"
        tabIndex={0}
        aria-label={`${artist.name}'s schedule — click to add appointment`}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            router.push(`/appointments/new?artist_id=${encodeURIComponent(artist.id)}`)
          }
        }}
      >
        {artist.bookings.map((b) => (
          <BookingBlock
            key={b.id}
            booking={b}
            artistColor={artist.artistColor}
            openMins={openMins}
            totalMins={totalMins}
          />
        ))}
      </div>
    </div>
  )
}

// ─── Hour header ──────────────────────────────────────────────────────────────

function HourHeader({
  openMins,
  totalMins,
}: {
  openMins: number
  totalMins: number
}) {
  const hours: number[] = []
  const startH = Math.floor(openMins / 60)
  const endH = Math.ceil((openMins + totalMins) / 60)
  for (let h = startH; h <= endH; h++) hours.push(h)

  return (
    <div className="relative flex" style={{ height: 24 }}>
      {/* Spacer for artist label column */}
      <div className="shrink-0 border-r border-[var(--color-border)]" style={{ width: 96 }} />
      <div className="relative flex-1 overflow-hidden">
        {hours.map((h) => {
          const pct = ((h * 60 - openMins) / totalMins) * 100
          if (pct < 0 || pct > 100) return null
          const label = h === 12 ? '12 PM' : h < 12 ? `${h} AM` : `${h - 12} PM`
          return (
            <span
              key={h}
              className="absolute bottom-0 -translate-x-1/2 select-none tabular-nums text-[9px] text-[var(--color-muted-foreground)]"
              style={{ left: `${pct}%` }}
              aria-hidden="true"
            >
              {label}
            </span>
          )
        })}
      </div>
    </div>
  )
}

// ─── Empty states ─────────────────────────────────────────────────────────────

function ClosedState() {
  return (
    <div className="flex flex-col items-center justify-center py-10 text-center">
      <p className="text-[13px] font-medium text-[var(--color-foreground)]">
        Studio closed today.
      </p>
      <p className="mt-1 text-[12px] text-[var(--color-muted-foreground)]">
        No schedule to display.
      </p>
    </div>
  )
}

function NoBookingsState() {
  return (
    <div className="flex flex-col items-center justify-center py-8 text-center">
      <p className="text-[13px] text-[var(--color-muted-foreground)]">
        No bookings scheduled for today.
      </p>
      <Link
        href="/appointments/new"
        className="mt-3 text-[12px] font-medium text-[var(--color-foreground)] underline underline-offset-2 hover:text-[var(--color-muted-foreground)]"
      >
        + New appointment
      </Link>
    </div>
  )
}

// ─── Widget ───────────────────────────────────────────────────────────────────

export function TodayScheduleTimelineWidget({ data }: TodayScheduleTimelineWidgetProps) {
  const { artists, openTime, closeTime, closedToday, hasBookings } = data

  const openMins = parseMins(openTime)
  const closeMins = parseMins(closeTime)
  const totalMins = Math.max(closeMins - openMins, 60) // guard zero

  const artistCount = artists.length
  const bookingCount = artists.reduce((s, a) => s + a.bookings.length, 0)

  const containerRef = useRef<HTMLDivElement>(null)

  return (
    <section
      aria-label="Today's schedule timeline"
      className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] shadow-[var(--shadow-soft)]"
    >
      {/* Header */}
      <div className="flex items-center justify-between border-b border-[var(--color-border)] px-4 py-3">
        <h2 className="text-[8.5px] font-bold uppercase tracking-[0.10em] text-[var(--color-foreground)]">
          Today&apos;s schedule
          {!closedToday && (
            <span className="ml-1.5 text-[var(--color-muted-foreground)] normal-case font-normal tracking-normal">
              · {artistCount} artist{artistCount !== 1 ? 's' : ''} · {bookingCount} booking{bookingCount !== 1 ? 's' : ''}
            </span>
          )}
        </h2>
        <Link
          href="/calendar?date=today"
          className="text-[7px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)] hover:text-[var(--color-foreground)] transition-colors"
          aria-label="Open full calendar"
        >
          Open calendar →
        </Link>
      </div>

      {/* Body */}
      <div className="overflow-hidden p-0">
        {closedToday ? (
          <ClosedState />
        ) : !hasBookings || artists.length === 0 ? (
          <NoBookingsState />
        ) : (
          <TooltipProvider>
            <div ref={containerRef} className="overflow-x-auto">
              {/* Hour header */}
              <HourHeader openMins={openMins} totalMins={totalMins} />

              {/* Artist rows with NOW line overlay */}
              <div className="relative">
                {/* Absolute NOW line — spans all rows */}
                <NowLine openMins={openMins} totalMins={totalMins} />

                {/* Grid lines (per hour) */}
                <div
                  className="pointer-events-none absolute inset-0 z-0"
                  aria-hidden="true"
                >
                  {Array.from({ length: Math.floor(totalMins / 60) + 1 }).map((_, i) => {
                    const pct = (i * 60) / totalMins * 100
                    return (
                      <div
                        key={i}
                        className="absolute inset-y-0 w-px bg-[var(--color-border)]"
                        style={{ left: `calc(96px + ${pct}% * (100% - 96px) / 100)` }}
                      />
                    )
                  })}
                </div>

                {/* Artist rows */}
                {artists.map((artist, idx) => (
                  <ArtistRow
                    key={artist.id}
                    artist={artist}
                    openMins={openMins}
                    totalMins={totalMins}
                    rowIndex={idx}
                  />
                ))}
              </div>
            </div>
          </TooltipProvider>
        )}
      </div>
    </section>
  )
}

