'use client'

import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { useTransition, useState, useRef, useEffect } from 'react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'
import { logger } from '@/lib/logger'
import { sendDepositReminderAction, resendFormLinkAction } from '@/app/(app)/inbox/actions'
import type { NextUpItem } from '@/lib/dashboard/next-up'

// ─── Props ─────────────────────────────────────────────────────────────────────

interface NextUpWidgetProps {
  items: NextUpItem[]
}

// ─── Avatar ───────────────────────────────────────────────────────────────────

function ArtistAvatar({ initials, artistColor }: { initials: string; artistColor: string | null }) {
  if (artistColor) {
    const bg = `color-mix(in srgb, ${artistColor} 18%, transparent)`
    return (
      <span
        className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-[11px] font-semibold"
        style={{ backgroundColor: bg, color: artistColor }}
        aria-hidden="true"
      >
        {initials}
      </span>
    )
  }

  return (
    <span
      className="inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[var(--color-muted)] text-[11px] font-semibold text-[var(--color-muted-foreground)]"
      aria-hidden="true"
    >
      {initials}
    </span>
  )
}

// ─── Status pill ──────────────────────────────────────────────────────────────

type PillVariant = 'success' | 'destructive' | 'muted'

function StatusPill({
  label,
  variant,
  onClick,
  loading,
}: {
  label: string
  variant: PillVariant
  onClick?: () => void
  loading?: boolean
}) {
  const base =
    'inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold transition-opacity'
  const styles: Record<PillVariant, string> = {
    success: 'bg-[var(--color-success-bg)] text-[var(--color-success-foreground)] cursor-default',
    destructive:
      'bg-[rgba(178,58,43,0.10)] text-[var(--color-rust)] cursor-pointer hover:opacity-80 active:opacity-60',
    muted: 'bg-[var(--color-muted)] text-[var(--color-muted-foreground)] cursor-pointer hover:opacity-80 active:opacity-60',
  }

  if (onClick) {
    return (
      <button
        type="button"
        className={cn(base, styles[variant], loading && 'pointer-events-none opacity-50')}
        onClick={(e) => {
          e.stopPropagation()
          onClick()
        }}
        disabled={loading}
        aria-label={label}
      >
        {label}
      </button>
    )
  }

  return <span className={cn(base, styles[variant])}>{label}</span>
}

// ─── Time display ─────────────────────────────────────────────────────────────

function formatTime(iso: string): string {
  return new Date(iso).toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  })
}

// ─── Card actions menu ────────────────────────────────────────────────────────

function CardActionsMenu({
  bookingId,
  depositPaid,
}: {
  bookingId: string
  depositPaid: boolean
}) {
  const router = useRouter()
  const [open, setOpen] = useState(false)
  const menuRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!open) return
    function handleClick(e: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClick)
    return () => document.removeEventListener('mousedown', handleClick)
  }, [open])

  return (
    <div className="relative" ref={menuRef}>
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation()
          setOpen((v) => !v)
        }}
        className="flex h-6 w-6 items-center justify-center rounded text-[var(--color-muted-foreground)] opacity-0 transition-opacity group-hover:opacity-100 hover:bg-[var(--color-muted)] hover:text-[var(--color-foreground)] focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--color-ring)]"
        aria-label="More actions"
        aria-haspopup="menu"
        aria-expanded={open}
      >
        <span className="text-[16px] leading-none">⋯</span>
      </button>

      {open && (
        <div
          role="menu"
          className="absolute right-0 top-full z-50 mt-1 min-w-[160px] rounded-lg border border-[var(--color-border)] bg-[var(--color-card)] py-1 shadow-[var(--shadow-lift)]"
        >
          {[
            {
              label: 'Reschedule',
              action: () => { router.push(`/calendar?reschedule=${bookingId}`); setOpen(false) },
              disabled: false,
              destructive: false,
            },
            {
              label: 'Cancel booking',
              action: () => { router.push(`/bookings/${bookingId}?action=cancel`); setOpen(false) },
              disabled: false,
              destructive: true,
            },
            {
              label: 'Send deposit reminder',
              action: async () => {
                setOpen(false)
                const result = await sendDepositReminderAction(bookingId)
                if (result.ok) toast.success('Reminder sent.')
                else toast.error(result.error ?? 'Failed to send reminder.')
              },
              disabled: depositPaid,
              destructive: false,
            },
            {
              label: 'Open client',
              action: () => { router.push(`/clients?booking=${bookingId}`); setOpen(false) },
              disabled: false,
              destructive: false,
            },
          ].map((item) => (
            <button
              key={item.label}
              type="button"
              role="menuitem"
              disabled={item.disabled}
              onClick={(e) => {
                e.stopPropagation()
                void item.action()
              }}
              className={cn(
                'flex w-full items-center px-3 py-1.5 text-left text-[12px] transition-colors disabled:cursor-not-allowed disabled:opacity-40',
                item.destructive
                  ? 'text-[var(--color-rust)] hover:bg-[rgba(178,58,43,0.06)]'
                  : 'text-[var(--color-foreground)] hover:bg-[var(--color-muted)]',
              )}
            >
              {item.label}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

// ─── Booking card ─────────────────────────────────────────────────────────────

function BookingCard({ item, isFirst }: { item: NextUpItem; isFirst: boolean }) {
  const router = useRouter()
  const [depositPending, startDeposit] = useTransition()
  const [consentPending, startConsent] = useTransition()

  function handleDepositPill() {
    startDeposit(async () => {
      const result = await sendDepositReminderAction(item.id)
      if (result.ok) {
        toast.success('Reminder sent.')
      } else {
        toast.error(result.error ?? 'Failed to send reminder.')
        logger.error({ bookingId: item.id, error: result.error }, 'next-up: deposit reminder failed')
      }
    })
  }

  function handleConsentPill() {
    startConsent(async () => {
      const result = await resendFormLinkAction(item.id)
      if (result.ok) {
        toast.success('Form resent.')
      } else {
        toast.error(result.error ?? 'Failed to resend form.')
        logger.error({ bookingId: item.id, error: result.error }, 'next-up: consent resend failed')
      }
    })
  }

  // Subtitle: "Service · S3 · 90 min · Lena"
  const subtitleParts: string[] = []
  if (item.serviceName) subtitleParts.push(item.serviceName)
  if (item.sessionLabel) subtitleParts.push(item.sessionLabel)
  subtitleParts.push(`${item.durationMin} min`)
  subtitleParts.push(item.artistName)

  const consentUnsigned = item.consentRequired && !item.consentSigned

  return (
    <div
      className={cn(
        'group relative rounded-lg border p-3 transition-all duration-150',
        'hover:shadow-[var(--shadow-card-hover)]',
        isFirst
          ? 'border-l-2 border-l-[var(--color-rust)] border-[var(--color-border)] bg-[var(--color-accent)]'
          : 'border-[var(--color-border)] bg-[var(--color-card)] hover:bg-[var(--color-secondary)]',
      )}
    >
      {/* Three-dot menu (top right) */}
      <div className="absolute right-2 top-2">
        <CardActionsMenu bookingId={item.id} depositPaid={item.depositPaid} />
      </div>

      {/* Card body — clickable */}
      <button
        type="button"
        onClick={() => router.push(`/bookings/${item.id}`)}
        className="flex w-full items-start gap-3 text-left focus-visible:outline-none"
        aria-label={`Booking for ${item.clientName} at ${formatTime(item.scheduledAt)}`}
      >
        {/* Time column */}
        <div className="shrink-0 text-right">
          <p className="tabular-nums text-[13px] font-bold leading-tight text-[var(--color-foreground)]">
            {formatTime(item.scheduledAt)}
          </p>
          {item.relativeLabel && (
            <p className="mt-0.5 tabular-nums text-[10px] leading-tight text-[var(--color-muted-foreground)]">
              {item.relativeLabel}
            </p>
          )}
        </div>

        {/* Avatar */}
        <ArtistAvatar initials={item.clientInitials} artistColor={item.artistColor} />

        {/* Main content */}
        <div className="min-w-0 flex-1 pr-6">
          <p className="truncate text-[13px] font-semibold leading-tight text-[var(--color-foreground)]">
            {item.clientName}
          </p>
          <p className="mt-0.5 truncate text-[11px] leading-tight text-[var(--color-muted-foreground)]">
            {subtitleParts.join(' · ')}
          </p>
        </div>
      </button>

      {/* Pills row — outside the navigate button */}
      <div className="mt-2 flex flex-wrap gap-1.5 pl-[calc(36px+12px+12px)]">
        {item.depositCents > 0 &&
          (item.depositPaid ? (
            <StatusPill label="Deposit paid" variant="success" />
          ) : (
            <StatusPill
              label="Deposit pending"
              variant="destructive"
              onClick={handleDepositPill}
              loading={depositPending}
            />
          ))}
        {item.consentRequired &&
          (item.consentSigned ? (
            <StatusPill label="Consent signed" variant="success" />
          ) : (
            <StatusPill
              label="Consent unsigned"
              variant={consentUnsigned ? 'destructive' : 'muted'}
              onClick={handleConsentPill}
              loading={consentPending}
            />
          ))}
      </div>
    </div>
  )
}

// ─── Empty state ──────────────────────────────────────────────────────────────

function EmptyState() {
  return (
    <div className="flex flex-col items-center justify-center py-8 text-center">
      <p className="text-[13px] text-[var(--color-muted-foreground)]">
        No confirmed bookings remaining today.
      </p>
      <Link
        href="/bookings/new"
        className="mt-3 text-[12px] font-medium text-[var(--color-foreground)] underline underline-offset-2 hover:text-[var(--color-muted-foreground)]"
      >
        + New booking
      </Link>
    </div>
  )
}

// ─── Widget ───────────────────────────────────────────────────────────────────

export function NextUpWidget({ items }: NextUpWidgetProps) {
  return (
    <section
      id="next-up"
      aria-label="Next up — upcoming bookings"
      className="rounded-xl border border-[var(--color-border)] bg-[var(--color-card)] shadow-[var(--shadow-card)]"
    >
      {/* Header */}
      <div className="flex items-center justify-between border-b border-[var(--color-border)] px-4 py-3">
        <h2 className="text-[8.5px] font-bold uppercase tracking-[0.10em] text-[var(--color-foreground)]">
          Next up
        </h2>
        <Link
          href="/calendar?date=today"
          className="text-[7px] font-medium uppercase tracking-[0.08em] text-[var(--color-muted-foreground)] transition-colors hover:text-[var(--color-foreground)]"
          aria-label="View all bookings on calendar"
        >
          View all →
        </Link>
      </div>

      {/* Body */}
      <div className="space-y-2 p-3">
        {items.length === 0 ? (
          <EmptyState />
        ) : (
          items.map((item, i) => <BookingCard key={item.id} item={item} isFirst={i === 0} />)
        )}
      </div>
    </section>
  )
}

